<?php require '_init.php';$pageTitle='Customer messages';if(post()){verify_csrf();query('UPDATE messages SET is_read=1-is_read WHERE id=?',[number('id')]);flash('Message updated.');redirect('admin/messages.php');}require '../includes/header.php';?><section class="container section"><h1>Messages</h1><?php $messages=query('SELECT * FROM messages ORDER BY is_read,id DESC')->fetchAll();if(!$messages)echo '<p class="panel">No messages yet.</p>';foreach($messages as $m):?><article class="panel order"><div class="section-head"><h3><?=e($m['name'])?></h3><span class="badge"><?=$m['is_read']?'Read':'New'?></span></div><p class="muted"><?=e($m['email'].' · '.$m['created_at'])?></p><p><?=nl2br(e($m['message']))?></p><form method="post"><?php csrf();?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="outline">Mark as <?=$m['is_read']?'unread':'read'?></button></form></article><?php endforeach;?></section><?php require '../includes/footer.php';?>
